"""Planted defects against the program frame (request parsing, role, dispatch). Used by tests/planted/runner.py with test_grammar.py and test_request.py."""
T = "tests"
BASE = "device/openwrt/newton-router/tests"
GR = [f"{BASE}/test_grammar.py", f"{BASE}/test_request.py"]

MUTANTS = [
    ("M1", "request class widened: ; | & $ allowed",
     'case "$req" in *[!][A-Za-z0-9\\ ._:/@+-]*) refuse bad-character 2 ;; esac',
     'case "$req" in *[!][A-Za-z0-9\\ ._:/@+;|&$-]*) refuse bad-character 2 ;; esac', GR),
    ("M1b", "request class widened: backtick and parentheses allowed",
     'case "$req" in *[!][A-Za-z0-9\\ ._:/@+-]*) refuse bad-character 2 ;; esac',
     'case "$req" in *[!][A-Za-z0-9\\ ._:/@+`()-]*) refuse bad-character 2 ;; esac', GR),
    ("M2", "set -f removed", "set -f\numask 077\n", "umask 077\n", GR),
    ("M3", "spacing check removed", "case \"$req\" in ' '*|*' '|*'  '*) refuse bad-spacing 2 ;; esac", ":", GR),
    ("M4", "17 tokens accepted (forced)", '[ "$#" -le 16 ] || refuse too-many-tokens 2\n\tif [ "${1-}" = /usr/libexec/newton/newton-router ]; then',
     '[ "$#" -le 17 ] || refuse too-many-tokens 2\n\tif [ "${1-}" = /usr/libexec/newton/newton-router ]; then', GR),
    ("M4b", "17 tokens accepted (direct)", '[ "$#" -le 16 ] || refuse too-many-tokens 2\n\t[ "$REQ_LEN" -le 1024 ]',
     '[ "$#" -le 17 ] || refuse too-many-tokens 2\n\t[ "$REQ_LEN" -le 1024 ]', GR),
    ("M5", "an empty request becomes a default command", '[ -n "$req" ] || refuse empty-request 2', '[ -n "$req" ] || req=hostname', GR),
    ("M7a", "SID: more than 32 hex accepted", 'is_sid() {\n\t[ "${#1}" -eq 32 ] || return 1', 'is_sid() {\n\t[ "${#1}" -ge 32 ] || return 1', GR),
    ("M7b", "SID: uppercase hex accepted", "is_sid() {\n\t[ \"${#1}\" -eq 32 ] || return 1\n\tcase \"$1\" in ''|*[!0-9a-f]*) return 1 ;; esac",
     "is_sid() {\n\t[ \"${#1}\" -eq 32 ] || return 1\n\tcase \"$1\" in ''|*[!0-9a-fA-F]*) return 1 ;; esac", GR),
    ("M7c", "SID: a prefix of 31 hex accepted", 'is_sid() {\n\t[ "${#1}" -eq 32 ] || return 1', 'is_sid() {\n\t[ "${#1}" -ge 31 ] && [ "${#1}" -le 32 ] || return 1', GR),
    ("M8", "leading-zero T accepted", "[1-9][0-9]|[1-9][0-9][0-9]) ;;", "[0-9][0-9]|[0-9][0-9][0-9]) ;;", GR),
    ("M8b", "T upper bound 601", '[ "$1" -ge 60 ] && [ "$1" -le 600 ]', '[ "$1" -ge 60 ] && [ "$1" -le 601 ]', GR),
    ("M8c", "T lower bound 59", '[ "$1" -ge 60 ] && [ "$1" -le 600 ]', '[ "$1" -ge 59 ] && [ "$1" -le 600 ]', GR),
    ("M9", "an extra argument accepted", 'if [ "$n" -lt "$SPEC_MIN" ] || [ "$n" -gt "$SPEC_MAX" ]; then',
     'if [ "$n" -lt "$SPEC_MIN" ] || [ "$n" -gt "$((SPEC_MAX + 1))" ]; then', GR),
    ("M9b", "one argument too few accepted", 'if [ "$n" -lt "$SPEC_MIN" ] || [ "$n" -gt "$SPEC_MAX" ]; then',
     'if [ "$n" -lt "$((SPEC_MIN - 1))" ] || [ "$n" -gt "$SPEC_MAX" ]; then', GR),
    ("M10", "read role allowed to stage", "stage) SPEC_ROLE=change ;;", "stage) SPEC_ROLE=read ;;", GR),
    ("M10b", "role check skipped", '\tif [ "$SPEC_ROLE" = change ] && [ "$ROLE" != change ]; then\n\t\t# fwrestart never refuses with 3: the host reads 3 as an\n\t\t# outcome (design 3.5).\n\t\tif [ "$sub" = fwrestart ]; then\n\t\t\tfail role 2\n\t\tfi\n\t\tfail role 3\n\tfi',
     '\tif false; then\n\t\t# fwrestart never refuses with 3: the host reads 3 as an\n\t\t# outcome (design 3.5).\n\t\tif [ "$sub" = fwrestart ]; then\n\t\t\tfail role 2\n\t\tfi\n\t\tfail role 3\n\tfi', GR),
    ("D1", "TOKEN accepts 32 hex (the defect found in review)", "is_token() {\n\tcase \"$1\" in none) return 0 ;; esac\n\t[ \"${#1}\" -eq 64 ] || return 1",
     "is_token() {\n\tcase \"$1\" in none) return 0 ;; esac\n\t[ \"${#1}\" -ge 32 ] || return 1", GR),
    ("M-order", "classes of seal swapped", "SPEC_CLASSES='sid t'; SPEC_ROLE=change; SPEC_OWNER=owner ;;\n\t\tdiff)", "SPEC_CLASSES='t sid'; SPEC_ROLE=change; SPEC_OWNER=owner ;;\n\t\tdiff)", GR),
    ("M-owner", "owner check skipped for non-root", '\t\t[ -d "$LOCK/$1.txn" ] || fail no-such-txn 3\n\t\tif [ "$CALLER" != root ]; then',
     '\t\t[ -d "$LOCK/$1.txn" ] || fail no-such-txn 3\n\t\tif false; then', GR + [f"{BASE}/test_apply.py", f"{BASE}/test_confirm.py"]),
    ("M-direct-only", "approval-selftest allowed in forced mode", 'if [ "$sub" = approval-selftest ] && [ "$DOOR" != root ]; then', 'if false; then', GR),
    ("M-rpcd", "--rpcd falls through to direct mode", "--rpcd) refuse door-not-built 2 ;;", "--rpcd) ;;", GR),
    ("M-keyline", "bad key line accepted as direct", "--caller=*|--role=*) refuse bad-key-line 2 ;;", "--caller=*|--role=*) ;;", GR),
    ("M-len1024", "request length limit 1025", '[ "${#req}" -le 1024 ] || refuse request-too-long 2', '[ "${#req}" -le 1025 ] || refuse request-too-long 2', GR),
    ("M-shift2", "the install path token shifted twice", '\tif [ "${1-}" = /usr/libexec/newton/newton-router ]; then\n\t\tshift\n\tfi',
     '\twhile [ "${1-}" = /usr/libexec/newton/newton-router ]; do\n\t\tshift\n\tdone', GR),
]
